<template><section class="module"><div class="head"><div><small>SEO AI OPERATIONS</small><h2>{{route.meta.title}}</h2><p>{{route.meta.description}}</p></div><el-button @click="load"><i class="fas fa-refresh"/> 刷新数据</el-button></div>
<template v-if="isLive"><div class="stats" v-if="overview"><article><span>组织</span><b>{{overview.organizations?.total||0}}</b></article><article><span>活跃站点</span><b>{{overview.sites?.total||0}}</b></article><article><span>完成扫描</span><b>{{overview.scans?.completed||0}}</b></article><article><span>待处理问题</span><b>{{overview.issues?.open||0}}</b></article></div>
<el-table :data="rows" v-loading="loading" stripe>
<template v-if="module==='sites'"><el-table-column prop="name" label="站点"/><el-table-column prop="base_url" label="地址" min-width="220"/><el-table-column prop="organization_name" label="组织"/><el-table-column prop="ownership_status" label="验证状态"/><el-table-column prop="last_score" label="分数"/><el-table-column prop="open_issues" label="待处理"/></template>
<template v-else-if="module==='scans'"><el-table-column prop="site_name" label="站点"/><el-table-column prop="organization_name" label="组织"/><el-table-column prop="status" label="状态"/><el-table-column prop="pages_scanned" label="页面"/><el-table-column prop="issue_count" label="问题"/><el-table-column prop="score" label="分数"/><el-table-column prop="created_at" label="开始时间" min-width="160"/></template>
<template v-else-if="module==='issues'"><el-table-column prop="severity" label="严重度"/><el-table-column prop="title" label="问题" min-width="180"/><el-table-column prop="site_name" label="站点"/><el-table-column prop="organization_name" label="组织"/><el-table-column prop="evidence" label="证据" min-width="260"/><el-table-column prop="status" label="状态"/></template>
<template v-else-if="module==='changes'"><el-table-column prop="severity" label="风险"/><el-table-column prop="title" label="变更候选" min-width="220"/><el-table-column prop="site_name" label="站点"/><el-table-column prop="organization_name" label="组织"/><el-table-column label="审核状态" width="150"><template #default="{row}"><el-select v-model="row.status" size="small" @change="reviewIssue(row)"><el-option label="待处理" value="open"/><el-option label="处理中" value="in_progress"/><el-option label="已解决" value="resolved"/><el-option label="忽略" value="ignored"/></el-select></template></el-table-column><el-table-column prop="updated_at" label="更新时间" min-width="170"/></template>
<template v-else-if="module==='usage'"><el-table-column prop="organization_name" label="组织" min-width="150"/><el-table-column prop="username" label="用户"/><el-table-column label="用量类型"><template #default="{row}">{{metricText[row.metric]||row.metric}}</template></el-table-column><el-table-column prop="quantity" label="数量"/><el-table-column prop="reference_type" label="来源"/><el-table-column prop="reference_id" label="关联编号"/><el-table-column prop="created_at" label="结算时间" min-width="170"/></template>
<template v-else-if="module==='connectors'"><el-table-column prop="normalized_host" label="站点" min-width="160"/><el-table-column prop="base_url" label="地址" min-width="220"/><el-table-column label="接口地址" min-width="220"><template #default="{row}">{{row.details?.endpoint||'未填写，使用站点默认接口'}}</template></el-table-column><el-table-column prop="organization_name" label="组织" min-width="140"/><el-table-column label="申请人" width="130"><template #default="{row}">{{row.display_name||row.username||'-'}}</template></el-table-column><el-table-column label="接入方式" width="110"><template #default="{row}">{{connectorText[row.details?.connector_type]||'-'}}</template></el-table-column><el-table-column label="审核状态" width="120"><template #default="{row}"><el-tag :type="row.review_status==='approved'?'success':row.review_status==='rejected'?'danger':'warning'">{{statusText[row.review_status]||'待审核'}}</el-tag></template></el-table-column><el-table-column prop="created_at" label="申请时间" min-width="170"/><el-table-column label="操作" fixed="right" width="150"><template #default="{row}"><el-button v-if="row.review_status==='pending'" type="success" link @click="reviewConnection(row,'approved')">批准</el-button><el-button v-if="row.review_status==='pending'" type="danger" link @click="reviewConnection(row,'rejected')">拒绝</el-button></template></el-table-column></template>
<template v-else-if="module==='audit-logs'"><el-table-column prop="action" label="操作" min-width="180"/><el-table-column prop="resource_type" label="资源" width="130"/><el-table-column prop="organization_name" label="组织" min-width="150"/><el-table-column label="操作者" width="140"><template #default="{row}">{{row.display_name||row.username||'-'}}</template></el-table-column><el-table-column prop="result" label="结果" width="90"/><el-table-column prop="ip_address" label="IP" width="140"/><el-table-column prop="created_at" label="时间" min-width="170"/></template>
<template v-else><el-table-column prop="name" label="套餐" min-width="130"/><el-table-column label="月付" width="115"><template #default="{row}"><el-input-number v-model="row.monthly_price" :min="0" :controls="false"/></template></el-table-column><el-table-column label="年付" width="125"><template #default="{row}"><el-input-number v-model="row.annual_price" :min="0" :controls="false"/></template></el-table-column><el-table-column label="站点" width="90"><template #default="{row}"><el-input-number v-model="row.entitlements.sites" :min="0" :controls="false"/></template></el-table-column><el-table-column label="成员" width="90"><template #default="{row}"><el-input-number v-model="row.entitlements.members" :min="0" :controls="false"/></template></el-table-column><el-table-column label="月抓取页" width="120"><template #default="{row}"><el-input-number v-model="row.entitlements.crawl_pages_monthly" :min="0" :controls="false"/></template></el-table-column><el-table-column label="单次页数" width="110"><template #default="{row}"><el-input-number v-model="row.entitlements.pages_per_scan" :min="0" :controls="false"/></template></el-table-column><el-table-column label="AI 点数" width="105"><template #default="{row}"><el-input-number v-model="row.entitlements.ai_points_monthly" :min="0" :controls="false"/></template></el-table-column><el-table-column label="扫描间隔(小时)" width="135"><template #default="{row}"><el-input-number v-model="row.entitlements.scan_interval_hours" :min="0" :controls="false"/></template></el-table-column><el-table-column label="订阅" prop="subscribers" width="70"/><el-table-column label="操作" fixed="right" width="90"><template #default="{row}"><el-button type="primary" link :loading="row.saving" @click="savePlan(row)">保存</el-button></template></el-table-column></template>
</el-table></template>
<template v-else><div class="ready"><i class="fas fa-circle-check"/> 模块遵循规则评分、AI 生成、人工审核、真实发布与复扫验证流程</div><div class="grid"><article v-for="f in route.meta.features" :key="f"><i class="fas fa-check"/><div><h3>{{f}}</h3><p>功能入口已按 Roadmap 规划，数据能力将随执行闭环逐步接入。</p></div><span>Roadmap</span></article></div></template></section></template>
<script setup>import{ref,computed,watch}from'vue';import{useRoute}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import api from'@/api';const route=useRoute(),loading=ref(false),rows=ref([]),overview=ref(null),module=computed(()=>route.params.module),isLive=computed(()=>['sites','scans','issues','changes','connectors','plans','usage','audit-logs'].includes(module.value)),metricText={crawl_page:'抓取页面',ai_point:'AI 点数',export:'报告导出',api_call:'API 调用'},connectorText={wordpress:'WordPress',rest:'REST API',webhook:'Webhook'},statusText={pending:'待审核',approved:'已批准',rejected:'已拒绝'};async function load(){if(!isLive.value)return;loading.value=true;try{const endpoint=module.value==='audit-logs'?'audit-logs':(module.value==='changes'?'issues':module.value==='connectors'?'connection-requests':module.value);const calls=[api.get('/admin/seo-operations/overview'),api.get('/admin/seo-operations/'+endpoint)];const[o,r]=await Promise.all(calls);overview.value=o.data;rows.value=r.data||[]}finally{loading.value=false}}async function reviewIssue(row){try{await api.put('/admin/seo-operations/issues/'+row.id+'/status',{status:row.status});ElMessage.success('审核状态已更新')}catch{load()}}async function reviewConnection(row,status){try{await ElMessageBox.confirm(status==='approved'?'批准后允许进入接入配置流程，是否继续？':'拒绝该接入申请，是否继续？','确认审核',{type:status==='approved'?'success':'warning'});await api.put('/admin/seo-operations/connection-requests/'+row.id,{status});row.review_status=status;ElMessage.success('接入申请审核完成')}catch(e){if(e!=='cancel')load()}}async function savePlan(row){row.saving=true;try{await api.put('/admin/seo-operations/plans/'+row.id,{monthly_price:row.monthly_price,annual_price:row.annual_price,entitlements:row.entitlements});ElMessage.success('套餐权益已保存')}finally{row.saving=false}}watch(module,load,{immediate:true})</script>
<style scoped>.module{max-width:1200px;margin:auto}.head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.head small{color:#1677ff;font-weight:700}.head h2{font-size:24px;margin:5px 0}.head p{color:#667085;margin:0}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:14px}.stats article{background:#fff;border:1px solid #e4e8ee;border-radius:7px;padding:15px}.stats span{font-size:11px;color:#667085}.stats b{display:block;font-size:24px;margin-top:5px}.ready{background:#eef8f5;border:1px solid #c7e9df;color:#276b5b;padding:12px 14px;border-radius:6px;margin-bottom:16px;font-size:13px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.grid article{display:grid;grid-template-columns:34px 1fr auto;background:#fff;border:1px solid #e4e8ee;border-radius:7px;padding:17px;gap:12px}.grid article>i{width:32px;height:32px;background:#eef4ff;color:#246bfd;border-radius:5px;display:flex;align-items:center;justify-content:center}.grid h3{font-size:14px;margin:0 0 6px}.grid p{font-size:12px;color:#667085;margin:0}.grid span{font-size:10px;color:#667085;background:#f2f4f7;padding:4px 6px;height:max-content;border-radius:3px}.el-input-number{width:100%}@media(max-width:700px){.grid,.stats{grid-template-columns:1fr 1fr}.head p{display:none}}</style>
